<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/includes/bootstrap.php';
$user = require_auth('landlord');
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $bookingId = filter_input(INPUT_POST, 'booking_id', FILTER_VALIDATE_INT); $action = (string) ($_POST['action'] ?? '');
    $stmt = db()->prepare('SELECT b.id, b.status FROM bookings b JOIN properties p ON p.id = b.property_id WHERE b.id = ? AND p.landlord_id = ?'); $stmt->execute([$bookingId, $user['id']]); $booking = $stmt->fetch();
    if (!$booking || $booking['status'] !== 'pending' || !in_array($action, ['approve', 'reject'], true)) { http_response_code(400); exit('Invalid booking action.'); }
    $status = $action === 'approve' ? 'approved' : 'rejected'; db()->prepare('UPDATE bookings SET status = ?, responded_at = NOW(), updated_at = NOW() WHERE id = ?')->execute([$status, $bookingId]); audit('booking.' . $status, 'booking', $bookingId); flash('success', 'Booking request ' . ($status === 'approved' ? 'approved.' : 'declined.')); redirect('landlord.php');
}
$propStmt = db()->prepare('SELECT * FROM properties WHERE landlord_id = ? ORDER BY created_at DESC'); $propStmt->execute([$user['id']]); $properties = $propStmt->fetchAll();
$bookStmt = db()->prepare('SELECT b.*, p.title, CONCAT(u.first_name, " ", u.last_name) AS student_name, u.email AS student_email FROM bookings b JOIN properties p ON p.id = b.property_id JOIN users u ON u.id = b.student_id WHERE p.landlord_id = ? ORDER BY FIELD(b.status,"pending","approved","deposit_held","completed","rejected"), b.created_at DESC'); $bookStmt->execute([$user['id']]); $bookings = $bookStmt->fetchAll();
$pageTitle='Landlord dashboard'; require dirname(__DIR__) . '/app/includes/header.php';
?>
<section class="dashboard-head section"><div><p class="eyebrow">Landlord dashboard</p><h1>Welcome, <?= e($user['first_name']) ?>.</h1><p>Respond quickly and keep students informed.</p></div><span class="status <?= $user['verified_at'] ? 'status-completed' : 'status-pending' ?>"><?= $user['verified_at'] ? 'Identity verified' : 'Verification pending' ?></span></section>
<section class="section metric-row"><article><span>Properties</span><strong><?= count($properties) ?></strong></article><article><span>Open requests</span><strong><?= count(array_filter($bookings, fn($b) => $b['status']==='pending')) ?></strong></article><article><span>Protected bookings</span><strong><?= count(array_filter($bookings, fn($b) => $b['status']==='deposit_held')) ?></strong></article></section>
<section class="section dashboard-grid"><div class="dashboard-main"><h2>Booking requests</h2><?php foreach ($bookings as $booking): ?><article class="request-card"><div><span class="status status-<?= e($booking['status']) ?>"><?= e(booking_status_label($booking['status'])) ?></span><h3><?= e($booking['student_name']) ?> · <?= e($booking['title']) ?></h3><p><?= e($booking['student_email']) ?> · Move-in <?= e(date('d M Y', strtotime($booking['move_in_date']))) ?></p><?php if ($booking['message']): ?><blockquote><?= e($booking['message']) ?></blockquote><?php endif; ?></div><?php if ($booking['status'] === 'pending'): ?><div class="action-row"><form method="post"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int) $booking['id'] ?>"><input type="hidden" name="action" value="approve"><button class="button" type="submit">Approve</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int) $booking['id'] ?>"><input type="hidden" name="action" value="reject"><button class="button button-danger" type="submit">Decline</button></form></div><?php endif; ?></article><?php endforeach; ?></div><aside class="dashboard-side"><div class="panel"><h2>Your properties</h2><?php foreach ($properties as $property): ?><div class="mini-property"><img src="<?= e(url('assets/img/'.$property['cover_image'])) ?>" alt=""><div><strong><?= e($property['title']) ?></strong><span><?= e(ucfirst($property['status'])) ?> · <?= (int)$property['available_rooms'] ?> rooms</span></div></div><?php endforeach; ?></div><div class="panel dark"><h2>12-hour standard</h2><p>Respond to non-instant requests before the displayed deadline to protect the platform promise.</p></div></aside></section>
<?php require dirname(__DIR__) . '/app/includes/footer.php'; ?>
